import React, { useState } from 'react';

function AttendanceData() {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [data] = useState([]);

  return (
    <div className="animate-fade-in">
      <div className="row g-3 mb-4">
        {[
          { icon: '👥', value: data.length, label: 'Tổng NV', color: '#4f46e5', bg: 'rgba(79,70,229,0.1)' },
          { icon: '✅', value: 0, label: 'Có Mặt', color: '#10b981', bg: 'rgba(16,185,129,0.1)' },
          { icon: '⏰', value: 0, label: 'Đi Muộn', color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
          { icon: '❌', value: 0, label: 'Vắng Mặt', color: '#ef4444', bg: 'rgba(239,68,68,0.1)' },
        ].map((c, i) => (
          <div className="col-md-3" key={i}>
            <div className="stat-card">
              <div className="stat-icon" style={{background: c.bg, color: c.color}}>{c.icon}</div>
              <div className="stat-value mt-2" style={{color: c.color}}>{c.value}</div>
              <div className="stat-label">{c.label}</div>
            </div>
          </div>
        ))}
      </div>
      <div className="content-card">
        <div className="card-header-custom">
          <h5>📅 Dữ Liệu Chấm Công</h5>
          <input type="date" className="form-control form-control-sm" style={{width: 180}}
            value={date} onChange={e => setDate(e.target.value)} />
        </div>
        <div className="table-responsive">
          <table className="table table-custom">
            <thead>
              <tr><th>Mã NV</th><th>Họ Tên</th><th>Ngày</th><th>Check In</th><th>Check Out</th><th>Giờ Công</th><th>Trạng Thái</th></tr>
            </thead>
            <tbody>
              <tr><td colSpan="7" className="text-center py-4 text-muted">Chưa có dữ liệu chấm công</td></tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default AttendanceData;
